return (async function(){
    var p = a[0];
    try {
        var tables = document.querySelectorAll('table');
        var best = null, bestRows = 0;
        for (var i = 0; i < tables.length; i++) {
            var n = tables[i].querySelectorAll('tbody tr').length;
